import{_ as t,o as e,c as n,ag as r}from"./chunks/framework.D5hoimZQ.js";const l=JSON.parse('{"title":"🔬 科学日报 | 2026年7月1日 · 深度扩展","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/science-daily/2026-07-01.md","filePath":"science-log/src/science-daily/2026-07-01.md"}'),a={name:"science-log/src/science-daily/2026-07-01.md"};function i(s,o,c,u,d,p){return e(),n("div",null,[...o[0]||(o[0]=[r('<h1 id="🔬-科学日报-2026年7月1日-·-深度扩展" tabindex="-1">🔬 科学日报 | 2026年7月1日 · 深度扩展 <a class="header-anchor" href="#🔬-科学日报-2026年7月1日-·-深度扩展" aria-label="Permalink to &quot;🔬 科学日报 | 2026年7月1日 · 深度扩展&quot;">​</a></h1><blockquote><p>来源：科学快报 第 11 期简讯（2026-07-01，共 11 条：科学前沿 6 篇 / AI 前沿 5 篇） 分析日期：2026-07-01 版本：扩展版（11 条深度 + 交叉关联） 核验：2026-11-07 经 CrossRef（DOI 逐条取题名/卷页/作者）、EuropePMC、arXiv abs 页核对，<strong>与简讯原文有出入处以核实结果为准并在正文标明</strong></p></blockquote><hr><h2 id="🔬-一、科学前沿" tabindex="-1">🔬 一、科学前沿 <a class="header-anchor" href="#🔬-一、科学前沿" aria-label="Permalink to &quot;🔬 一、科学前沿&quot;">​</a></h2><h3 id="_1-多层镍酸盐超导相图首次完整勾勒" tabindex="-1">1. 多层镍酸盐超导相图首次完整勾勒 <a class="header-anchor" href="#_1-多层镍酸盐超导相图首次完整勾勒" aria-label="Permalink to &quot;1. 多层镍酸盐超导相图首次完整勾勒&quot;">​</a></h3><p><strong>原文</strong>：Science 报道了一项镍酸盐超导体的重要突破（DOI: 10.1126/science.adp4440）。研究团队系统绘制了多层四方平面镍酸盐 (La,Pr,Sm)₃Ni₂O₇ 薄膜的超导相图，揭示了在不同电子掺杂和压力条件下的超导转变行为。</p><p><strong>深度扩展</strong>：</p><p>核验后需修正简讯的一处混淆：<code>10.1126/science.adp4440</code> 的题名是 <em>Superconducting phase diagram of multilayer square-planar nickelates</em>（Science 392 卷 1390–1395 页，2026-06-25 上线），作者 24 人，第一作者 Grace A. Pan、Dan Ferenc Segedin，单位是哈佛大学物理系（Julia Mundy 组）；研究对象<strong>不是</strong> (La,Pr,Sm)₃Ni₂O₇，而是 Ndₙ₊₁NiₙO₂ₙ₊₂ 多层膜的维度序列。简讯里提到的 (La,Pr,Sm)₃Ni₂O₇ 属于同期的姊妹论文 <code>10.1126/science.adw8329</code>（Science 392 卷 1396–1400 页，沈建昌等，中国科学技术大学/合肥国家实验室）。</p><p>两篇合起来才是完整图景。哈佛组把 n=4 到 n=8 的多层结构逐层做出来，发现每一层都能超导；随 n 减小，超导各向异性因 4f 电子效应而系统性演化，电子结构逐步靠近铜氧化物（cuprate-like）；磁涨落不只在超导区存在，一直延伸到过掺杂的非超导区——这是&quot;磁涨落驱动配对&quot;最直接的相图级证据。</p><p>中科大组则用超高真空低温解理-转移技术，对 (La,Pr,Sm)₃Ni₂O₇ 薄膜做角分辨光电子能谱，沿布里渊区对角线测到约 18 meV 的超导能隙与相干峰，且能隙在整个布里渊区都有限、没有节点，从而判定为无节点配对，并提取出电子-玻色子耦合谱。</p><p><strong>跨主题关联</strong>：与 <code>topics/quantum-physics/index.md</code> 的配对机制讨论、<code>topics/materials/index.md</code> 的强关联氧化物薄膜工艺同源；2026-07-02 的日报也覆盖了这条 DOI，可对读。</p><hr><h3 id="_2-gw250114-直接测到黑洞视界的-拖曳回响" tabindex="-1">2. GW250114：直接测到黑洞视界的&quot;拖曳回响&quot; <a class="header-anchor" href="#_2-gw250114-直接测到黑洞视界的-拖曳回响" aria-label="Permalink to &quot;2. GW250114：直接测到黑洞视界的&quot;拖曳回响&quot;&quot;">​</a></h3><p><strong>原文</strong>：Nature 发表了 LIGO-Virgo-KAGRA 合作组对 GW250114 事件的深度分析。这是迄今信噪比最高的黑洞合并事件，科学家成功从合并后的&quot;铃荡&quot;（ringdown）阶段提取出视界存在的高置信度特征。</p><p><strong>深度扩展</strong>：</p><p><code>10.1038/s41586-026-10696-0</code>（<em>GW250114 reveals signatures of post-merger black-hole horizon</em>，Nature 655 卷 71–75 页，2026-06-24）只有 5 位作者：Neil Lu、Sizheng Ma、Ornella J. Piccinni、陈雁北（Yanbei Chen）、孙凌（Ling Sun）——这是一篇理论/数据分析文章，不是合作组官方探测论文，简讯把它写成&quot;合作组分析&quot;并不准确。</p><p>它检验的也不是普通的准正常模（QNM），而是 2025 年理论预言的**&quot;直接波&quot;（direct wave）**：落入黑洞的物体会被参考系拖曳强行锁定在以视界角速度 Ω_H 旋转的轨道上，它发出的引力波因此以接近 2Ω_H 的频率振荡，并按视界表面重力 κ 决定的速率指数衰减——这是&quot;视界本身&quot;的印记，而不是轨道动力学的遗留。</p><p>匹配滤波结果：LIGO Hanford 在 90% 置信度下信噪比 15.8 (+0.1/−0.5)，Livingston 为 17.1 (+0.1/−0.4)。测得的频率与衰减率与 Kerr 黑洞的理论预言完全一致。这为&quot;无毛定理&quot;提供了迄今为止最直接的一类检验，也打开了一条在强场动力学区测量能层参考系拖曳的观测通道。</p><p><strong>跨主题关联</strong>：<code>topics/physics/index.md</code>（广义相对论检验）、<code>topics/philosophy/index.md</code>（&quot;不可见之物如何被间接观测&quot;的认识论问题）。</p><hr><h3 id="_3-人眼视锥色素冷冻电镜结构-颜色视觉的分子底座" tabindex="-1">3. 人眼视锥色素冷冻电镜结构：颜色视觉的分子底座 <a class="header-anchor" href="#_3-人眼视锥色素冷冻电镜结构-颜色视觉的分子底座" aria-label="Permalink to &quot;3. 人眼视锥色素冷冻电镜结构：颜色视觉的分子底座&quot;">​</a></h3><p><strong>原文</strong>：Science 同期发表三篇姊妹文章，首次用冷冻电镜解析了人眼红、绿、蓝三种视锥色素的高分辨率结构，揭示了视黄醛（retinal）发色团如何与蛋白口袋结合并被&quot;调谐&quot;到不同波长范围。</p><p><strong>深度扩展</strong>：</p><p>三篇同期刊于 Science 392 卷（均为 2026-06-25 上线），但分工并不对称，核验后的题名如下：</p><ul><li><code>10.1126/science.adz3624</code> <em>Illuminating the molecular basis of human daylight vision</em>（Schmidt、Dostal、Sen 等 12 人，主要单位 Paul Scherrer 研究所与 ETH Zürich）：解析人蓝敏 OPN1SW 与绿敏 OPN1MW 的暗态冷冻电镜结构，叠加飞秒分辨光谱、功能测定与分子模拟。</li><li><code>10.1126/science.adz3996</code> <em>Structural insights into spectral tuning and retinal exchange in cone visual pigments</em>（大橋さやか、片山航太等）：聚焦光谱调谐与视黄醛交换路径。</li><li><code>10.1126/science.adz8141</code> <em>Cryo–electron microscopy structures of human cone visual pigments</em>（彭琦、李健、蒋海海等）：人视锥色素的结构学总图。</li></ul><p>核心发现是三件事。其一，三种视锥共用同一个发色团 11-顺视黄醛，波长差异完全来自蛋白口袋的静电环境——口袋内极性残基的位置决定 Schiff 碱质子化态的能量，从而把吸收峰在蓝（~420 nm）、绿（~530 nm）、红（~560 nm）之间挪动。其二，三种色素的发色团稳定机制各不相同，说明&quot;同一个零件、三套装配工艺&quot;。其三，GPCR 的&quot;微开关&quot;（microswitch）基序在视锥中发生了序列特化，这解释了视锥为何能在强光下快速失活（毫秒级），而不像视杆视紫红质那样慢。</p><p>意义在于：色盲、视网膜色素变性的突变位点大多落在这些被结构定位的口袋残基与微开关上，结构一旦可读，基因治疗与小分子&quot;光谱位移&quot;设计就有了坐标。</p><p><strong>跨主题关联</strong>：<code>topics/neuroscience/index.md</code>（感觉转导）、<code>topics/biomedicine/index.md</code>（GPCR 药理学的通用价值）。</p><hr><h3 id="_4-单细胞多组学-精神疾病风险位点的-情境开关" tabindex="-1">4. 单细胞多组学：精神疾病风险位点的&quot;情境开关&quot; <a class="header-anchor" href="#_4-单细胞多组学-精神疾病风险位点的-情境开关" aria-label="Permalink to &quot;4. 单细胞多组学：精神疾病风险位点的&quot;情境开关&quot;&quot;">​</a></h3><p><strong>原文</strong>：Science 上的大规模单细胞研究（DOI: 10.1126/science.adw3949）分析了不同脑区、不同激活状态下神经元的染色质可及性、RNA 表达和蛋白丰度，构建了&quot;上下文-基因-疾病&quot;的三维图谱。</p><p><strong>深度扩展</strong>：</p><p><code>10.1126/science.adw3949</code> 的实测内容与简讯描述有偏差，需更正：题名 <em>Single-cell multiomics of neuron activation reveals context-specific genetics of brain disorders</em>（Science 392 卷，2026-06-25），第一作者梁丽凡（Lifan Liang）、张思伟（Siwei Zhang），通讯单位为芝加哥大学人类遗传学系与 Endeavor Health 精神遗传学中心，共 21 位作者。研究材料<strong>不是</strong>人脑切片，而是 100 位供者的<strong>诱导多能干细胞（iPSC）分化神经元</strong>，做单核 RNA+ATAC 多组学，并对比&quot;静息 vs 刺激激活&quot;两种状态。</p><p>三个关键数字与结论：一，在激活状态下鉴定出大量与活性依赖基因表达、染色质可及性相关的遗传变异；二，其中染色质可及性那一类，解释的精神疾病遗传力<strong>比例更高</strong>——也就是说，非编码区的&quot;开关&quot;比编码区的&quot;零件&quot;更能解释风险；三，与 GWAS 整合后，浮现出一批<strong>只在刺激后才显效</strong>的风险基因，典型例子是活性依赖的胆固醇代谢通路。</p><p>这直接改写了&quot;风险基因&quot;的定义：它不是恒定表达的坏零件，而是被错误调度的开关。对药物开发的含义是，靶点筛选必须在&quot;正确的激活窗口&quot;里做，用静息态细胞筛，会漏掉大部分真正的效应。</p><p><strong>跨主题关联</strong>：<code>topics/neuroscience/index.md</code>、<code>topics/biomedicine/index.md</code>；方法学上与 <code>topics/intelligence-self-learning/index.md</code> 的&quot;上下文决定表征&quot;同构。</p><hr><h3 id="_5-菱面体石墨烯-磁场-助力-超导的新家族" tabindex="-1">5. 菱面体石墨烯：磁场&quot;助力&quot;超导的新家族 <a class="header-anchor" href="#_5-菱面体石墨烯-磁场-助力-超导的新家族" aria-label="Permalink to &quot;5. 菱面体石墨烯：磁场&quot;助力&quot;超导的新家族&quot;">​</a></h3><p><strong>原文</strong>：Nature 报道了在菱面体多层石墨烯中发现的&quot;磁场增强超导&quot;家族（DOI: 10.1038/s41586-026-10815-x）。通常磁场会破坏超导，但在这类系统中，平行磁场不仅没有削弱，反而显著提升超导转变温度。</p><p><strong>深度扩展</strong>：</p><p><code>10.1038/s41586-026-10815-x</code>（<em>Family of magnetic field-boosted superconductors in rhombohedral graphene</em>，Nature 656 卷 60–66 页，2026-06-29）共 21 位作者，第一作者 Junseok Seo、Armel A. Cotten，通讯作者为康奈尔大学的 L. Ju（巨磊）；器件由 Watanabe/Taniguchi 提供 hBN 晶体，理论/测量侧还有 D. M. Zumbühl 参与。</p><p>实验对象是菱面体（rhombohedral）<strong>四层与五层</strong>石墨烯的输运测量。关键结果有三条：一，在五层体系中找到<strong>三种</strong>不同类型的磁场增强型与磁场诱导型超导；二，它们对<strong>面内</strong>磁场直到 8.5 T 仍然稳定，超出 Pauli 极限数十倍——Pauli 极限是&quot;磁场拆散库珀对&quot;的经典上限，超出几十倍意味着配对电子并非简单自旋单态；三，与 Bernal 双层石墨烯只在面内磁场下增强不同，五层体系在<strong>面外</strong>磁场下也能被增强，且因为能带更平坦，所需的栅极电场低得多，实验窗口宽、可工程化。此外，引入邻近自旋轨道耦合还能在不增加无序的前提下&quot;生&quot;出多个新超导相。</p><p>物理含义是：若时间反演对称性可以与规范对称性分离地破缺，就会出现&quot;磁场是助力而非敌人&quot;的超导——这正是非常规配对（如 FFLO、同位旋/自旋-谷锁定）的判据场。石墨烯因此从&quot;复现铜氧化物的玩具&quot;变成&quot;可调参数最干净的非常规超导平台&quot;。</p><p><strong>跨主题关联</strong>：<code>topics/physics/index.md</code>、<code>topics/quantum-physics/index.md</code>、<code>topics/materials/index.md</code>（二维材料与拓扑超导）。</p><hr><h3 id="_6-2400-°c-仍保-100-mpa-可铸可加工的-ta-基合金" tabindex="-1">6. 2400 °C 仍保 100 MPa：可铸可加工的 Ta 基合金 <a class="header-anchor" href="#_6-2400-°c-仍保-100-mpa-可铸可加工的-ta-基合金" aria-label="Permalink to &quot;6. 2400 °C 仍保 100 MPa：可铸可加工的 Ta 基合金&quot;">​</a></h3><p><strong>原文</strong>：Nature 报道了一种新型韧性合金（DOI: 10.1038/s41586-026-10708-z），在 2400°C 仍能维持 100 MPa 的抗拉强度——这是现有镍基高温合金的极限温度 1100°C 的两倍以上。</p><p><strong>深度扩展</strong>：</p><p><code>10.1038/s41586-026-10708-z</code>（<em>Ductile alloys offering 100 MPa tensile strength at 2,400 °C</em>，Nature 655 卷 109–115 页，2026-06-24），作者 7 人：薛敏涛、李苏植、王静、李金阳、丁向东、En Ma（毛恩）、孙军。这是一支纯国内的强关联&quot;计算+实验&quot;组合，长期做难熔金属与纳米析出强化。</p><p>工艺是本文的真正创新点：<strong>硼介入的原位氧化反应</strong>（boron-intervened in situ oxidation）。用硼先稳住 HfO₂（氧化铪），在 Ta 基体里原位生成约 <strong>50 nm</strong> 直径的氧化物颗粒，并让它们在<strong>晶粒内部</strong>密集、均匀地弥散。这解决了难熔合金几十年的死结：陶瓷相能提供高温强度，但加进去就变脆；金属基体韧性好，但 2000 °C 以上强度塌方。</p><p>三个结果：一，2400 °C 下抗拉强度仍有 100 MPa，填补了该温区的空白；二，室温下仍保持可加工塑性，可用铸造+变形工艺做成复杂形状件，而不是只能烧结的脆块；三，晶内弥散（而非晶界偏聚）使得颗粒在长期高温下不易粗化，抗 Ostwald 熟化能力显著优于传统析出相。</p><p>工程意义落在三处：高超声速飞行器的前缘与燃烧室、可重复使用火箭发动机喷管、核反应堆包壳。涡轮前温度每提高 100 °C，热效率约升 1–2%，这类材料把上限从 1100 °C 推到 2400 °C，是数量级的空间。</p><p><strong>跨主题关联</strong>：<code>topics/materials/index.md</code>（高温合金/难熔金属）、<code>topics/wind-energy/index.md</code>（燃气轮机与热端部件材料需求）、<code>topics/space-energy/index.md</code>（火箭发动机与再入热防护）。</p><hr><h2 id="🤖-二、ai-前沿" tabindex="-1">🤖 二、AI 前沿 <a class="header-anchor" href="#🤖-二、ai-前沿" aria-label="Permalink to &quot;🤖 二、AI 前沿&quot;">​</a></h2><h3 id="_7-ai-模型网络-ai-modelnet-把-计算机-连成-互联网" tabindex="-1">7. AI 模型网络（AI-ModelNet）：把&quot;计算机&quot;连成&quot;互联网&quot; <a class="header-anchor" href="#_7-ai-模型网络-ai-modelnet-把-计算机-连成-互联网" aria-label="Permalink to &quot;7. AI 模型网络（AI-ModelNet）：把&quot;计算机&quot;连成&quot;互联网&quot;&quot;">​</a></h3><p><strong>原文</strong>：arXiv: <a href="https://arxiv.org/abs/2606.27382" target="_blank" rel="noreferrer">2606.27382</a> 论文提出 AI-Model Network（AMN）的概念与架构框架，类比互联网对计算机的赋能：单个大模型是&quot;计算机&quot;，而 AMN 则是&quot;互联网&quot;。</p><p><strong>深度扩展</strong>：</p><p>核验后的正式题名是 <em>AI-Model Network: Concept, Current State and Future</em>（arXiv:2606.27382，abs 页已核对存在且题名一致）。作者的立论起点很朴素：大模型的实际落地被两件事卡住——训练成本高、部署复杂；于是行业转向轻量、私有、领域专用模型。结果是异构模型数量爆炸式增长，&quot;让它们互相发现、互相调用&quot;成为新的瓶颈。</p><p>论文的类比链条是：计算机之于互联网 ≈ 单模型之于模型网络。互联网的价值不在单机算力，而在 TCP/IP 这种<strong>标准化协议</strong>让任意两台机器可以通信；同理，模型网络的价值不在单个权重，而在让任意两个模型可以交换能力。为此它给出概念、愿景与系统架构三层，讨论能力注册与发现、调用编排、以及计费与治理这类&quot;互联网级&quot;必需件。</p><p>值得注意的是，这是一篇<strong>立场与架构</strong>文章（concept paper），核心贡献是问题定义与分层设计，而非新的实验结果或基准分数——读它应当读它的接口抽象，不要期待 SOTA 数字。</p><p><strong>跨主题关联</strong>：<code>topics/ai-system-architecture/index.md</code>（系统分层与协议设计）、<code>topics/ai-tools/index.md</code>（工具生态的类比）。</p><hr><h3 id="_8-多智能体团队的-人格组合-任务结构决定一切" tabindex="-1">8. 多智能体团队的&quot;人格组合&quot;：任务结构决定一切 <a class="header-anchor" href="#_8-多智能体团队的-人格组合-任务结构决定一切" aria-label="Permalink to &quot;8. 多智能体团队的&quot;人格组合&quot;：任务结构决定一切&quot;">​</a></h3><p><strong>原文</strong>：arXiv: <a href="https://arxiv.org/abs/2606.27443" target="_blank" rel="noreferrer">2606.27443</a> 研究者系统测试了在多智能体系统中给不同 agent 分配不同&quot;人格提示&quot;对协作任务表现的影响。结果出人意料：人格组合是否有效高度依赖任务领域。</p><p><strong>深度扩展</strong>：</p><p>正式题名 <em>When Does Personality Composition Matter for Multi-Agent LLM Teams?</em>（arXiv:2606.27443，abs 页核对一致）。实验设计是干净的三因子：人格维度（宜人性高/低等）× 前沿 LLM × 三个任务域，三个域分别是<strong>结构化编程</strong>、<strong>开放式研究协作</strong>、<strong>竞争性谈判</strong>。</p><p>结论比简讯转述的更精确，也更反直觉：</p><ul><li>编程任务里，低宜人性人格产生<strong>大幅度的沟通风格偏移</strong>，但里程碑完成率几乎不变——说话变凶了，活还是干完了。也就是说&quot;沟通风格&quot;与&quot;任务产出&quot;在这类任务里解耦。</li><li>开放式协作与谈判里，同一个操纵却<strong>显著降低</strong>表现。原因不难推：这两类任务依赖信息交换与让步，而人格提示直接改写了&quot;愿不愿意让出信息&quot;的收益函数。</li><li>由此可以提炼出一个可操作的判据：<strong>任务结构越接近&quot;可分解 + 可验证&quot;，人格操纵越无害；越接近&quot;需要协商 + 信息不对称&quot;，人格操纵越有害</strong>。</li></ul><p>这篇的方法论价值大于结论价值：它把&quot;给 agent 设人格&quot;从凭直觉的工艺，变成了可以在三个轴上做对照实验的变量。对 CrewAI / AutoGen / LangGraph 这类框架的直接含义是，人格配置应当按任务类型分档，而不是全局统一。</p><p><strong>跨主题关联</strong>：<code>topics/ai-system-architecture/index.md</code>（多智能体编排）、<code>topics/psychology/index.md</code>（人格维度与群体决策）。</p><hr><h3 id="_9-内化未来-把世界模型压进自回归模型本身" tabindex="-1">9. 内化未来：把世界模型压进自回归模型本身 <a class="header-anchor" href="#_9-内化未来-把世界模型压进自回归模型本身" aria-label="Permalink to &quot;9. 内化未来：把世界模型压进自回归模型本身&quot;">​</a></h3><p><strong>原文</strong>：arXiv: <a href="https://arxiv.org/abs/2606.27483" target="_blank" rel="noreferrer">2606.27483</a> 这篇论文训练单个自回归模型同时<strong>输出计划 + 模拟该计划的未来轨迹</strong>，让模型在生成动作前先&quot;在脑子里走一遍&quot;。在多个长视野决策基准上显著优于 ReAct、Reflexion 等基线。</p><p><strong>深度扩展</strong>：</p><p>正式题名 <em>Internalizing the Future: A Unified Agentic Training Paradigm for World Model Planning</em>（arXiv:2606.27483）。问题陈述很锐利：LLM agent 在长视野任务中是<strong>反应式</strong>的，缺少人类的&quot;what-if&quot;——先模拟再承诺。标准解法是外挂一个 simulator，但那是两套系统、两次调用、两倍延迟。</p><p>作者的做法是把两样东西都verbalize（言语化）出来：一段<strong>前瞻性状态推演</strong>（state rollout），加一个<strong>计划条件下的成功估计</strong>（plan-conditioned success estimate）——后者被明确定位为 Q 值的文本类比。</p><p>真正有价值的是它发现并命名的一个坑：<strong>格式-能力落差</strong>（format-capability gap）。如果只在后训练阶段拿&quot;前瞻轨迹&quot;做微调，模型会学到<strong>表面上的深谋远虑</strong>——输出格式对了，但并没有真正的预测性 grounding，等于学会了&quot;像在思考&quot;而不是&quot;在思考&quot;。为填这个落差，论文提出三阶段训练：先用 World Model Agentic Mid-Training（WM-AMT）把潜在预测能力注入策略；再用 Format-Eliciting SFT（FE-SFT）把这份能力结构化表达出来；第三阶段做对齐收口。</p><p>这条&quot;先灌能力、再教格式&quot;的顺序，是对当下主流&quot;直接 SFT 轨迹数据&quot;的一记提醒：<strong>格式可以模仿，能力不能</strong>。</p><p><strong>跨主题关联</strong>：<code>topics/intelligence-self-learning/index.md</code>（自我改进的闭环结构）、<code>topics/ai-brain/index.md</code>（&quot;外脑&quot;是否需要内建世界模型）。</p><hr>',81)])])}const q=t(a,[["render",i]]);export{l as __pageData,q as default};
